#include <iostream>
#include <vector>

struct Cell {
    int height;
};

std::vector<Cell> terrain{{1}, {2}, {3}};
int lookups = 0;

std::vector<Cell>& active_terrain() {
    ++lookups;
    return terrain;
}

int main() {
    for (auto cell : active_terrain()) {
        cell.height *= 10;
    }

    for (auto& cell : terrain) {
        cell.height += 1;
    }

    int total = 0;
    for (const auto& cell : terrain) {
        total += cell.height;
    }

    std::cout << lookups << ' ' << total << '\n';
}

#include <iostream>
#include <type_traits>

struct Counted {
    inline static int copies = 0;

    int value;

    Counted(int initial) : value(initial) {}
    Counted(const Counted& other) : value(other.value) { ++copies; }
};

struct Extent {
    Counted width;
    Counted height;
};

int main() {
    Extent extent{Counted{4}, Counted{5}};

    auto [w, h] = extent;
    std::cout << Counted::copies << ' ';

    auto& [live_width, live_height] = extent;
    live_width.value = 9;

    std::cout << Counted::copies << ' '
              << extent.width.value << ' '
              << std::boolalpha
              << std::is_same_v<decltype(live_width), Counted> << '\n';
}

