// <version> is what publishes the library feature-test macros; a language
// macro such as __cpp_explicit_this_parameter comes from the compiler and
// needs no header at all.
#include <version>

#include <string_view>

// Gate on the FEATURE, never on __cplusplus. A language-mode value says which
// edition was selected, not which parts of it this compiler and this standard
// library actually implement - and implementations routinely backport features
// into older modes or ship them years apart from each other.
#if defined(__cpp_lib_print) && __cpp_lib_print >= 202207L

#include <print>

inline void emit(std::string_view line) {
    std::print("{}\n", line);
}

#else

#include <cstdio>
#include <string>

inline void emit(std::string_view line) {
    std::fputs(std::string{line}.c_str(), stdout);
    std::fputc('\n', stdout);
}

#endif

// Feature macros carry dates, not booleans, so a revision can be requested.
// An absent or older value means the path below is not available here.
#if defined(__cpp_explicit_this_parameter) && \
    __cpp_explicit_this_parameter >= 202110L

struct Level {
    int severity_;

    template<class Self>
    decltype(auto) severity(this Self&& self) {
        return (static_cast<Self&&>(self).severity_);
    }
};

#else

struct Level {
    int severity_;

    int& severity() & { return severity_; }
    const int& severity() const& { return severity_; }
};

#endif

// One call site, whichever branch was taken.
inline void report(const Level& level) {
    emit(level.severity() > 2 ? "high" : "low");
}

#include <iostream>
#include <string>
#include <string_view>
#include <vector>

struct Document {
    std::string body;

    std::string_view text() const { return body; }
};

int scans = 0;

Document& open_document() {
    ++scans;  // deliberately observable
    static Document document{"tile,tile,tile"};
    return document;
}

void count_commas() {
    int commas = 0;

    // The range expression is evaluated ONCE, so open_document() runs once
    // however many characters there are. `const auto&` copies nothing.
    for (const char& c : open_document().text()) {
        if (c == ',') ++commas;
    }

    // The same loop with the exposition-only variables spelled out. This is
    // where "once" is visible: the hidden reference is initialised once and
    // the two endpoints are obtained once, before the loop begins.
    auto&& hidden_range = open_document().text();
    auto hidden_begin = hidden_range.begin();
    auto hidden_end = hidden_range.end();
    for (; hidden_begin != hidden_end; ++hidden_begin) {
        const char& c = *hidden_begin;
        if (c == ',') ++commas;
    }

    std::cout << scans << ' ' << commas << '\n';  // prints: 2 4
}

void iterate_a_temporary() {
    // C++23 extends the lifetime of temporaries created inside the range
    // initialiser through the loop, so the Document survives the iteration.
    // Before C++23 only the outer temporary bound to the hidden reference was
    // extended, and this exact loop was undefined behaviour.
    for (char c : Document{"FAST"}.text()) {
        std::cout << c;
    }
    std::cout << '\n';
}

void element_declarations(std::vector<std::string>& tokens) {
    // Copies each element: correct only when the copy is intended.
    for (auto token : tokens) static_cast<void>(token);
    // Mutates in place.
    for (auto& token : tokens) token.push_back('!');
    // Neither copies nor permits mutation: the default for reading.
    for (const auto& token : tokens) static_cast<void>(token);
}

#include <cstddef>
#include <iostream>
#include <map>
#include <string>
#include <tuple>
#include <utility>

// The class keeps its representation private, so the third protocol (bind the
// non-static data members) is not available to callers. Opting into the
// tuple-like protocol is what makes `auto [w, h] = box;` legal anyway.
class Extent {
public:
    Extent(int width, int height) : width_(width), height_(height) {}

    template<std::size_t Index>
    auto get() const {
        if constexpr (Index == 0) return width_;
        else return height_;
    }

private:
    int width_;
    int height_;
};

template<>
struct std::tuple_size<Extent> : std::integral_constant<std::size_t, 2> {};

template<std::size_t Index>
struct std::tuple_element<Index, Extent> {
    using type = int;
};

std::tuple<int, int> viewport() {
    return {1920, 1080};
}

void report(std::map<std::string, int>& tiles) {
    // The declaration before `[` initialises ONE hidden object; the names are
    // bindings into it, not two independent variables. `auto` makes a copy of
    // the whole thing, `auto&` binds the original.
    auto [width, height] = viewport();
    std::cout << width << 'x' << height << '\n';

    // Tuple-like protocol via tuple_size / tuple_element / get.
    Extent box{64, 32};
    auto [box_width, box_height] = box;
    std::cout << box_width << 'x' << box_height << '\n';

    // `auto&` binds the entry itself, so the increment lands in the map. A
    // by-value binding would copy the whole pair - std::string key included -
    // for every entry, even though only one name is written.
    for (auto& [name, count] : tiles) {
        static_cast<void>(name);
        ++count;
    }
}

#include <algorithm>
#include <compare>
#include <cstdint>
#include <set>
#include <string>

// Defaulting compares members in DECLARATION order, so representation order
// becomes comparison order. The wire format below happens to store the patch
// field first; rearranging the members to suit the comparison would change the
// layout, so the spaceship is written out instead.
struct Version {
    std::uint16_t patch;
    std::uint16_t minor;
    std::uint16_t major;

    friend std::strong_ordering operator<=>(const Version& left,
                                            const Version& right) {
        if (auto order = left.major <=> right.major; order != 0) return order;
        if (auto order = left.minor <=> right.minor; order != 0) return order;
        return left.patch <=> right.patch;
    }

    // A HAND-WRITTEN <=> declares no ==, so equality must be supplied. It is
    // also usually cheaper than a full ordering, which is why the language
    // keeps them separate.
    friend bool operator==(const Version& left, const Version& right) {
        return left.major == right.major && left.minor == right.minor
            && left.patch == right.patch;
    }
};

struct Tag {
    std::string text;

    static char fold(char c) {
        return c >= 'A' && c <= 'Z' ? static_cast<char>(c - 'A' + 'a') : c;
    }

    // WEAK, not strong: "Beta" and "beta" are equivalent under this ordering
    // but observably different objects, so equal values are not substitutable.
    friend std::weak_ordering operator<=>(const Tag& left, const Tag& right) {
        return std::lexicographical_compare_three_way(
            left.text.begin(), left.text.end(),
            right.text.begin(), right.text.end(),
            [](char a, char b) { return fold(a) <=> fold(b); });
    }

    friend bool operator==(const Tag& left, const Tag& right) {
        return (left <=> right) == 0;
    }
};

// Both give a strict weak ordering, so both are usable as set keys. A defaulted
// <=> over a double member would yield partial_ordering instead, and NaN would
// break the container's requirements.
bool checks() {
    std::set<Version> releases{Version{9, 0, 1}, Version{0, 0, 2}};
    std::set<Tag> tags{Tag{"Beta"}, Tag{"beta"}};

    return *releases.begin() == Version{9, 0, 1}
        && tags.size() == 1
        && Version{9, 0, 1} < Version{0, 0, 2};
}

#include <array>
#include <cstddef>
#include <cstdint>
#include <string_view>

enum class State : std::uint8_t { Idle, Reading, Escaped, Failed };

// constexpr: PERMITTED in a constant expression, and required to run at
// compile time only where one is required. An ordinary call still runs at
// run time.
constexpr State advance(State current, char input) {
    switch (current) {
        case State::Idle:
            return input == '"' ? State::Reading : State::Idle;
        case State::Reading:
            if (input == '\\') return State::Escaped;
            return input == '"' ? State::Idle : State::Reading;
        case State::Escaped:
            return State::Reading;
        default:
            return State::Failed;
    }
}

// Four states by 128 ASCII inputs, folded flat and built by the compiler.
constexpr auto make_table() {
    std::array<State, 4 * 128> table{};
    for (std::size_t state = 0; state < 4; ++state) {
        for (std::size_t input = 0; input < 128; ++input) {
            table[state * 128 + input] =
                advance(static_cast<State>(state), static_cast<char>(input));
        }
    }
    return table;
}

// The table ships in read-only data instead of being generated at startup.
inline constexpr auto transition_table = make_table();
static_assert(transition_table[static_cast<std::size_t>(State::Idle) * 128 + '"']
              == State::Reading);
static_assert(transition_table[static_cast<std::size_t>(State::Reading) * 128
                               + '\\'] == State::Escaped);

// consteval: an IMMEDIATE function. Every potentially evaluated call must be a
// constant expression, so a run-time call is a compile error by design - which
// is what makes this a validator rather than a check.
consteval std::size_t escape_free_length(std::string_view literal) {
    for (char c : literal) {
        if (c == '\\') throw "escape sequences are not allowed here";
    }
    return literal.size();
}

constexpr std::size_t prompt_length = escape_free_length("ready> ");
static_assert(prompt_length == 7);

// constinit: constrains INITIALISATION only. No dynamic initialisation and no
// first-use guard, but the object stays mutable - unlike a constexpr variable,
// which is also const.
constinit std::size_t documents_scanned = 0;

// if consteval (C++23) lets one function take a different path during constant
// evaluation without any template machinery.
constexpr std::size_t budget() {
    if consteval {
        return 0;  // no run-time budget is being spent
    } else {
        return 1;
    }
}

static_assert(budget() == 0);

State scan(std::string_view text) {
    auto state = State::Idle;
    for (char c : text) {
        const auto index = static_cast<std::size_t>(state) * 128
                         + static_cast<unsigned char>(c);
        state = transition_table[index];
    }
    documents_scanned += budget();  // 1 at run time
    return state;
}

#include <string>
#include <type_traits>
#include <utility>

// Before: four members that differ only in the qualification of the object,
// and whose bodies are identical.
struct BufferBefore {
    std::string bytes_;

    std::string& bytes() & { return bytes_; }
    const std::string& bytes() const& { return bytes_; }
    std::string&& bytes() && { return std::move(bytes_); }
    const std::string&& bytes() const&& { return std::move(bytes_); }
};

struct Buffer {
    std::string bytes_;

    // One member. Self is deduced exactly like a forwarding reference, so it
    // becomes Buffer&, const Buffer&, or Buffer at the call site, and the
    // return type follows.
    template<class Self>
    decltype(auto) bytes(this Self&& self) {
        // The parentheses are load-bearing. decltype(auto) applies decltype
        // rules to the return expression, and decltype of an UNPARENTHESISED
        // member access reports the member's declared type - so writing
        // `return std::forward<Self>(self).bytes_;` would return std::string
        // BY VALUE for every Self, silently losing the property this member
        // exists to provide. Parenthesised, decltype sees an lvalue or xvalue
        // expression instead.
        return (std::forward<Self>(self).bytes_);
    }

    // No implicit `this` is available inside an explicit-object member: every
    // member must be reached through self. Such a function also cannot be
    // declared virtual.
    template<class Self>
    std::size_t size(this Self&& self) {
        return self.bytes_.size();
    }
};

struct Extent {
    int width;
    int height;

    // By value: self is a copy, so the original is untouched. For a small
    // trivially copied type this can travel in registers rather than through
    // an implicit pointer.
    Extent scaled(this Extent self, int factor) {
        self.width *= factor;
        self.height *= factor;
        return self;
    }
};

// The contract, checked by the compiler: const-ness and value category survive.
using Lvalue = decltype(std::declval<Buffer&>().bytes());
using ConstLvalue = decltype(std::declval<const Buffer&>().bytes());
using Rvalue = decltype(std::declval<Buffer&&>().bytes());

static_assert(std::is_same_v<Lvalue, std::string&>);
static_assert(std::is_same_v<ConstLvalue, const std::string&>);
static_assert(std::is_same_v<Rvalue, std::string&&>);

// A caller binding the rvalue case still owns the lifetime problem: the
// returned std::string&& refers to a member of a temporary that dies at the
// end of the full-expression.
inline std::string take(Buffer&& buffer) {
    return std::move(buffer).bytes();
}
